import React, { useState, useEffect } from 'react';
import './Ahorro.css'; // Asegúrate de importar el archivo CSS

const Ahorro = ({ user }) => {
    const [saveForm, setSaveForm] = useState({
        hasSpecificGoal: false,
        targetAmount: 'No especificado',
        weeklySavings: 'No especificado'
    });
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [objectives, setObjectives] = useState([{ amount: '', term: '', quantity: '' }]);
    const [savingsPlan, setSavingsPlan] = useState([]);

    useEffect(() => {
        const fetchFormData = async () => {
            if (!user || !user._id) {
                console.warn('El usuario no está definido o no tiene un _id');
                setLoading(false);
                return;
            }

            try {
                const response = await fetch(`http://localhost:5000/api/forms/save/getSave/${user._id}`);
                if (!response.ok) {
                    throw new Error(`Error en la respuesta: ${response.status}`);
                }
                const result = await response.json();
                setSaveForm({
                    hasSpecificGoal: result.hasSpecificGoal || false,
                    targetAmount: result.targetAmount || 'No especificado',
                    weeklySavings: result.weeklySavings || 'No especificado'
                });
            } catch (error) {
                console.error('Error fetching form data:', error);
                setError(error.message);
            } finally {
                setLoading(false);
            }
        };

        fetchFormData();
    }, [user]);

    const handleObjectiveChange = (index, event) => {
        const { name, value } = event.target;
        const updatedObjectives = [...objectives];
        updatedObjectives[index][name] = value;
        setObjectives(updatedObjectives);
    };

    const addObjective = () => {
        setObjectives([...objectives, { amount: '', term: '', quantity: '' }]);
    };

    const removeObjective = (index) => {
        const updatedObjectives = objectives.filter((_, i) => i !== index);
        setObjectives(updatedObjectives);
        calculateSavingsPlan(updatedObjectives);
    };

    // Función para calcular el plan de ahorro
    const calculateSavingsPlan = (objectives) => {
        const plan = objectives.map((objective) => {
            const { amount, term, quantity } = objective;
            const targetAmount = parseFloat(amount);
            const quantityNumber = parseFloat(quantity);

            if (isNaN(targetAmount) || isNaN(quantityNumber) || quantityNumber <= 0) {
                return null;
            }

            let periods = 0;
            let savingsPerPeriod = 0;
            let label = '';

            switch (term) {
                case 'mensual':
                    periods = Math.ceil(targetAmount / quantityNumber);
                    savingsPerPeriod = quantityNumber;
                    label = 'Mes(es)';
                    break;
                case 'semanal':
                    periods = Math.ceil(targetAmount / (quantityNumber * 4)); // Aproximadamente 4 semanas en un mes
                    savingsPerPeriod = quantityNumber * 4;
                    label = 'Semana(s)';
                    break;
                case 'diario':
                    periods = Math.ceil(targetAmount / (quantityNumber * 30)); // Aproximadamente 30 días en un mes
                    savingsPerPeriod = quantityNumber * 30;
                    label = 'Día(s)';
                    break;
                default:
                    return null;
            }

            return { targetAmount, periods, savingsPerPeriod, label };
        }).filter(Boolean);

        setSavingsPlan(plan);
    };

    const handleAddObjective = () => {
        addObjective();
        calculateSavingsPlan([...objectives, { amount: '', term: '', quantity: '' }]);
    };

    if (loading) {
        return <div className="loading">Cargando...</div>;
    }

    if (error) {
        return <div className="error">Error: {error}</div>;
    }

    return (
        <div className="ahorro-container">
            <h1 className="ahorro-title">Ahorro</h1>
            <div className="tables-container">
                {/* Tabla de Objetivos de Ahorro */}
                <div className="table-wrapper objectives-wrapper">
                    <h2>Objetivos de Ahorro</h2>
                    <table className="objectives-table">
                        <thead>
                            <tr>
                                <th>Objetivo Monto ($)</th>
                                <th>Plazo</th>
                                <th>Cantidad ($)</th>
                                <th>Acciones</th>
                            </tr>
                        </thead>
                        <tbody>
                            {objectives.map((objective, index) => (
                                <tr key={index}>
                                    <td>
                                        <input
                                            type="number"
                                            name="amount"
                                            value={objective.amount}
                                            onChange={(e) => {
                                                handleObjectiveChange(index, e);
                                                calculateSavingsPlan(objectives);
                                            }}
                                            placeholder="Monto"
                                            min="0"
                                        />
                                    </td>
                                    <td>
                                        <select
                                            name="term"
                                            value={objective.term}
                                            onChange={(e) => {
                                                handleObjectiveChange(index, e);
                                                calculateSavingsPlan(objectives);
                                            }}
                                        >
                                            <option value="">Seleccionar</option>
                                            <option value="semanal">Semanal</option>
                                            <option value="mensual">Mensual</option>
                                            <option value="diario">Diario</option>
                                        </select>
                                    </td>
                                    <td>
                                        <input
                                            type="number"
                                            name="quantity"
                                            value={objective.quantity}
                                            onChange={(e) => {
                                                handleObjectiveChange(index, e);
                                                calculateSavingsPlan(objectives);
                                            }}
                                            placeholder="Cantidad"
                                            min="0"
                                        />
                                    </td>
                                    <td>
                                        <button className="delete-button" onClick={() => removeObjective(index)}>Eliminar</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    <button className="add-button" onClick={handleAddObjective}>Agregar Objetivo</button>
                </div>

                {/* Tabla del Plan de Ahorro */}
                <div className="table-wrapper plan-wrapper">
                    <h2>Plan de Ahorro</h2>
                    {savingsPlan.length > 0 ? (
                        <table className="plan-table">
                            <thead>
                                <tr>
                                    <th>Objetivo ($)</th>
                                    <th>Plazo</th>
                                    <th>Períodos Necesarios</th>
                                    <th>Ahorros por Período ($)</th>
                                </tr>
                            </thead>
                            <tbody>
                                {savingsPlan.map((plan, index) => (
                                    <tr key={index}>
                                        <td>${plan.targetAmount.toLocaleString()}</td>
                                        <td>{plan.label}</td>
                                        <td>{plan.periods}</td>
                                        <td>${plan.savingsPerPeriod.toLocaleString()}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    ) : (
                        <p>No hay plan de ahorro generado.</p>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Ahorro;
